<template><div class="page"><el-tabs v-model="tab" @tab-change="loadAll"><el-tab-pane label="商品" name="products"><el-button type="primary" @click="openCreate">新增商品</el-button><el-table :data="products"><el-table-column prop="productName" label="商品"/><el-table-column prop="categoryName" label="分类"/><el-table-column prop="salePrice" label="售价"/><el-table-column prop="stock" label="库存"/><el-table-column prop="status" label="状态"/><el-table-column label="操作"><template #default="s"><el-button link @click="openEdit(s.row)">编辑</el-button></template></el-table-column></el-table></el-tab-pane><el-tab-pane label="订单" name="orders"><el-table :data="orders"><el-table-column prop="orderNo" label="订单号" min-width="190"/><el-table-column prop="nickname" label="会员"/><el-table-column prop="payableAmount" label="金额"/><el-table-column prop="deliveryType" label="配送"/><el-table-column prop="status" label="状态"/><el-table-column label="操作"><template #default="s"><el-button v-if="s.row.status==='PAID'" type="primary" link @click="ship(s.row)">发货</el-button></template></el-table-column></el-table></el-tab-pane><el-tab-pane label="售后" name="after"><el-table :data="afterSales"><el-table-column prop="afterSaleNo" label="售后单" min-width="190"/><el-table-column prop="orderNo" label="订单"/><el-table-column prop="nickname" label="会员"/><el-table-column prop="reason" label="原因"/><el-table-column prop="paidAmount" label="退款金额"/><el-table-column prop="status" label="状态"/><el-table-column label="操作" width="170"><template #default="s"><template v-if="['PENDING','REFUND_FAILED'].includes(s.row.status)"><el-button type="success" link @click="approve(s.row)">{{s.row.status==='REFUND_FAILED'?'重试退款':'退款'}}</el-button><el-button v-if="s.row.status==='PENDING'" type="danger" link @click="reject(s.row)">拒绝</el-button></template></template></el-table-column></el-table></el-tab-pane></el-tabs><el-dialog v-model="visible" :title="form.productId?'编辑商品':'新增商品'" width="560px"><el-form label-width="80px"><el-form-item label="名称"><el-input v-model="form.productName"/></el-form-item><el-form-item label="分类"><el-input v-model="form.categoryName"/></el-form-item><el-form-item label="售价"><el-input-number v-model="form.salePrice" :min="0.01" :precision="2"/></el-form-item><el-form-item label="库存"><el-input-number v-model="form.stock" :min="0"/></el-form-item><el-form-item label="主图"><image-upload v-model="form.coverUrl" :limit="1"/></el-form-item><el-form-item label="详情"><el-input v-model="form.detailText" type="textarea" maxlength="2000" show-word-limit/></el-form-item><el-form-item label="上架"><el-switch v-model="onSale"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
<script setup>import{onMounted,ref}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import{getXyProducts,saveXyProduct,getXyOrders,shipXyOrder,getXyAfterSales,approveXyAfterSale,rejectXyAfterSale}from'@/api/xy';const tab=ref('products'),products=ref([]),orders=ref([]),afterSales=ref([]),visible=ref(false),onSale=ref(true);const blank=()=>({productId:null,productName:'',categoryName:'',salePrice:0,stock:0,coverUrl:'',detailText:'',status:'0',sortOrder:0}),form=ref(blank());async function loadAll(){[products.value,orders.value,afterSales.value]=await Promise.all([getXyProducts(),getXyOrders(),getXyAfterSales()])}function openCreate(){form.value=blank();onSale.value=true;visible.value=true}function openEdit(row){form.value={...row};onSale.value=row.status==='0';visible.value=true}async function save(){await saveXyProduct({...form.value,status:onSale.value?'0':'1'});visible.value=false;ElMessage.success('已保存');loadAll()}async function ship(row){await shipXyOrder(row.orderNo);ElMessage.success('已发货');loadAll()}async function approve(row){await ElMessageBox.confirm('确认按订单实付金额原路退款？','退款确认',{type:'warning'});await approveXyAfterSale(row.afterSaleNo);ElMessage.success('退款已提交微信处理');loadAll()}async function reject(row){await rejectXyAfterSale(row.afterSaleNo);ElMessage.success('已拒绝');loadAll()}onMounted(loadAll)</script><style scoped>.page{padding:20px;background:#fff;border-radius:16px}.el-table{margin-top:16px}</style>
